#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_mojo;
uniform float amzp_tint;
uniform float amzp_punch;
uniform float amzp_bleach;
uniform float amzp_fade;
uniform float amzp_blueSqueeze;
uniform float amzp_skinSqueeze;
uniform float amzp_exposure;
uniform float amzp_coolWarm;
uniform float amzp_greenMagenta;
uniform float amzp_skinYellowPink;
uniform float amzp_preserveHighlights;
uniform float amzp_protectSkinTones;





        float3 rgb2hsv(float3 c) {
            float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
            float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
            float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));

            float d = q.x - min(q.w, q.y);
            float e = 1.0e-10;
            return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
        }

        float3 hsv2rgb(float3 c) {
            float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
            float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
            return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
        }


        bool isSkinTone(float3 rgb) {
            float3 hsv = rgb2hsv(rgb);
            float h = hsv.x; 
            float s = hsv.y;
            float v = hsv.z;



            bool hueRange = (h > 0.02 && h < 0.16); 
            bool satRange = (s > 0.1 && s < 0.85); 
            bool valRange = (v > 0.15 && v < 0.95); 

            return hueRange && satRange && valRange;
        }


        float3 applyMojo(float3 rgb) {
            float mojoStrength = amzp_mojo * 0.01;


            rgb *= pow(2.0, amzp_exposure);


            if (amzp_coolWarm != 0.0) {
                float temp = amzp_coolWarm * 0.01 * mojoStrength;
                rgb.r += temp * 0.15;
                rgb.b -= temp * 0.15;
                rgb = clamp(rgb, 0.0, 1.0);
            }


            if (amzp_greenMagenta != 0.0) {
                float amzp_tint = amzp_greenMagenta * 0.01 * mojoStrength;
                rgb.g += amzp_tint * 0.15;
                rgb = clamp(rgb, 0.0, 1.0);
            }


            if (amzp_punch != 0.0) {
                float punchStrength = amzp_punch * 0.01 * mojoStrength;
                float3 contrast = mix(float3(0.5), rgb, 1.0 + punchStrength * 0.5);
                rgb = contrast;
                rgb = clamp(rgb, 0.0, 1.0);
            }


            if (amzp_bleach != 0.0) {
                float bleachStrength = amzp_bleach * 0.01 * mojoStrength;
                float luminance = dot(rgb, float3(0.299, 0.587, 0.114));
                float3 bleachColor = mix(rgb, float3(luminance), 0.5 * bleachStrength);
                rgb = mix(rgb, bleachColor, mojoStrength);
                rgb = clamp(rgb, 0.0, 1.0);
            }


            if (amzp_fade != 0.0) {
                float fadeStrength = amzp_fade * 0.01 * mojoStrength;
                float3 fadeColor = mix(rgb, float3(0.5, 0.5, 0.5), fadeStrength);
                rgb = fadeColor;
                rgb = clamp(rgb, 0.0, 1.0);
            }


            if (amzp_blueSqueeze != 0.0) {
                float luminance = dot(rgb, float3(0.299, 0.587, 0.114));
                float blueSqueezeStrength = amzp_blueSqueeze * 0.01 * mojoStrength;


                if (luminance < 0.7) {
                    float shadowFactor = (0.7 - luminance) / 0.7;
                    rgb.b += blueSqueezeStrength * shadowFactor * 0.2;
                    rgb.r -= blueSqueezeStrength * shadowFactor * 0.1;
                    rgb = clamp(rgb, 0.0, 1.0);
                }
            }


            if (amzp_skinSqueeze != 0.0) {
                if (isSkinTone(rgb)) {
                    float skinSqueezeStrength = amzp_skinSqueeze * 0.01 * mojoStrength;
                    float3 hsv = rgb2hsv(rgb);


                    hsv.y = mix(hsv.y, min(hsv.y * 1.3, 1.0), skinSqueezeStrength);


                    if (hsv.x < 0.04) { 
                        hsv.x = mix(hsv.x, 0.08, skinSqueezeStrength * 0.3);
                    } else if (hsv.x > 0.13) { 
                        hsv.x = mix(hsv.x, 0.10, skinSqueezeStrength * 0.3);
                    }

                    rgb = hsv2rgb(hsv);
                    rgb = clamp(rgb, 0.0, 1.0);
                }
            }


            if (amzp_skinYellowPink != 0.0) {
                if (isSkinTone(rgb)) {
                    float skinAdjust = amzp_skinYellowPink * 0.01 * mojoStrength;
                    float3 hsv = rgb2hsv(rgb);


                    hsv.x = clamp(hsv.x + skinAdjust * 0.08, 0.03, 0.14);

                    rgb = hsv2rgb(hsv);
                    rgb = clamp(rgb, 0.0, 1.0);
                }
            }


            if (amzp_tint != 0.0) {
                float tintStrength = amzp_tint * 0.01 * mojoStrength;
                float3 tintColor = float3(1.0 + tintStrength * 0.2, 1.0, 1.0 - tintStrength * 0.2);
                rgb *= tintColor;
                rgb = clamp(rgb, 0.0, 1.0);
            }

            return rgb;
        }


        float3 protectHighlights(float3 rgb) {
            if ((amzp_preserveHighlights>0.5)) {
                float maxChannel = max(max(rgb.r, rgb.g), rgb.b);
                if (maxChannel > 0.95) {
                    float highlightReduction = (maxChannel - 0.95) / 0.05;
                    rgb = mix(rgb, clamp(rgb, 0.0, 0.95), highlightReduction * 0.5);
                }
            }
            return rgb;
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float4 original = amzTexture(0, uv);
            float3 rgb = original.rgb;


            float3 mojoColor = applyMojo(rgb);


            mojoColor = protectHighlights(mojoColor);


            float3 finalColor = mix(rgb, mojoColor, amzp_mojo * 0.01);


            finalColor = clamp(finalColor, 0.0, 1.0);


            amzOutput = float4(finalColor, original.a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

